const fs = await import('node:fs');
const { existsSync } = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
if (!inputPath) throw new Error('Missing INPUT_PATH');
if (!existsSync(inputPath)) throw new Error('Input file does not exist: ' + inputPath);
globalThis.inputPath = inputPath;

const mod = await import('pdf-text-extract');
const extract = mod.default || mod;
if (typeof extract !== 'function') throw new Error('pdf-text-extract export is not a function');
const result = await new Promise((resolve, reject) => {
  extract(globalThis.inputPath, { splitPages: false }, (err, text) => {
    if (err) return reject(err);
    resolve(text);
  });
});
globalThis.result = result;
